export function laneHeight(value,standard,latched=false){const n=Math.max(Math.min(32,standard),Math.min(320,value)),snapped=Math.abs(n-standard)<=(latched?14:8);return{height:Math.round(snapped?standard:n),snapped}}
export function createTimelineLaneSizing({status=()=>{}}={}){
 let prefs={};try{prefs=JSON.parse(localStorage.getItem('pve.timeline.lane-heights')||'{}')||{}}catch{}
 const persist=()=>{try{localStorage.setItem('pve.timeline.lane-heights',JSON.stringify(prefs))}catch{}};
 const lanes=()=>[...[0,1,2].map(i=>({track:document.getElementById(['videoTrack','videoTrackUpper','videoTrackTop'][i]),head:document.querySelector(`[data-videohead="${i}"]`),kind:'video',label:'V'+(i+1)})),...[0,1,2].map(i=>({track:document.getElementById('overlayTrack'+i),head:document.querySelector(`[data-overlayhead="${i}"]`),kind:'overlay',label:'F/T'+(i+1)})),...[0,1,2,3].map(i=>({track:document.getElementById('audioTrack'+i),head:document.getElementById('audioLabel'+i),kind:'audio',label:'A'+(i+1)}))];
 const apply=()=>{for(const lane of lanes()){
  const{track,head,kind,label}=lane;if(!track||!head)continue;const property='--timeline-'+kind+'-lane',key=(document.body.dataset.ui==='phone'?'phone:':'desktop:')+track.id;
  for(const node of[track,head])node.style.removeProperty(property);const standard=parseFloat(getComputedStyle(track).getPropertyValue(property))||44;
  const set=(height,snapped=false)=>{for(const node of[track,head])node.style.setProperty(property,height+'px');for(const handle of[...track.querySelectorAll('[data-lane-resize]'),...head.querySelectorAll('[data-lane-resize]')]){handle.setAttribute('aria-valuenow',height);handle.setAttribute('aria-valuetext',height+'px · 標準 '+standard+'px');handle.classList.toggle('is-default',snapped)}status(label+' · '+height+'px'+(snapped?' · 標準に吸着':' · 標準 '+standard+'px'))};
  const commit=(height)=>{if(height===standard)delete prefs[key];else prefs[key]=height;persist()};
  const reset=()=>{set(standard,true);commit(standard)};
  for(const node of[track,head]){let handle=node.querySelector(':scope > [data-lane-resize]');if(!handle){handle=document.createElement('button');handle.dataset.laneResize=track.id;handle.className='timeline-lane-resizer';handle.setAttribute('role','separator');handle.setAttribute('aria-orientation','horizontal');handle.setAttribute('aria-label',label+'の高さを調整');handle.setAttribute('aria-valuemin','32');handle.setAttribute('aria-valuemax','320');node.append(handle)}handle.title=label+'の高さを調整 · 標準付近で吸着 · ダブルクリックで戻す';
   handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();handle.setPointerCapture(e.pointerId);const y=e.clientY,start=track.getBoundingClientRect().height;let current=start,latched=Math.abs(start-standard)<.5;handle.classList.add('resizing');handle.onpointermove=move=>{move.preventDefault();move.stopPropagation();const result=laneHeight(start+move.clientY-y,standard,latched);latched=result.snapped;current=result.height;set(current,latched)};const finish=(event,cancel=false)=>{event.stopPropagation();if(cancel)set(start,Math.abs(start-standard)<.5);else commit(current);handle.classList.remove('resizing');handle.onpointermove=handle.onpointerup=handle.onpointercancel=null;try{handle.releasePointerCapture(event.pointerId)}catch{}};handle.onpointerup=e=>finish(e);handle.onpointercancel=e=>finish(e,true)};
   handle.onclick=e=>{e.preventDefault();e.stopPropagation()};handle.ondblclick=e=>{e.preventDefault();e.stopPropagation();reset()};handle.onkeydown=e=>{if(!['ArrowUp','ArrowDown','Home','Enter'].includes(e.key))return;e.preventDefault();e.stopPropagation();if(e.key==='Home'||e.key==='Enter')return reset();const next=laneHeight(track.getBoundingClientRect().height+(e.key==='ArrowDown'?16:-16),standard);set(next.height,next.snapped);commit(next.height)};
  }
  const height=Number.isFinite(prefs[key])?laneHeight(prefs[key],standard).height:standard;for(const node of[track,head])node.style.setProperty(property,height+'px');for(const handle of[...track.querySelectorAll('[data-lane-resize]'),...head.querySelectorAll('[data-lane-resize]')]){handle.setAttribute('aria-valuenow',height);handle.setAttribute('aria-valuetext',height+'px · 標準 '+standard+'px');handle.classList.toggle('is-default',height===standard)}
 }};return{apply};
}
